import{_ as c,C as p,o as t,c as m,j as i,a as s,b as o,w as a,E as r,a3 as d,a2 as l}from"./chunks/framework.CZqXuAiL.js";const y=JSON.parse('{"title":"Architecture Overview","description":"GameFilter XDP internals — the aya-eBPF kernel program, userspace loader/CLI, API daemon, OpenShield sync, map layout (FILTER_MAP, PORT_MAP, ADMIT_MAP, FAIL_MAP, WHITELIST/BLACKLIST, STATS, CONFIG), the packet pipeline, and the admission/ban state machine.","frontmatter":{"title":"Architecture Overview","description":"GameFilter XDP internals — the aya-eBPF kernel program, userspace loader/CLI, API daemon, OpenShield sync, map layout (FILTER_MAP, PORT_MAP, ADMIT_MAP, FAIL_MAP, WHITELIST/BLACKLIST, STATS, CONFIG), the packet pipeline, and the admission/ban state machine."},"headers":[],"relativePath":"gamefilter-xdp/architecture/overview.md","filePath":"gamefilter-xdp/architecture/overview.md","lastUpdated":null}'),A={name:"gamefilter-xdp/architecture/overview.md"};function h(u,e,f,b,P,g){const n=p("Mermaid");return t(),m("div",null,[e[3]||(e[3]=i("h1",{id:"architecture-overview",tabindex:"-1"},[s("Architecture Overview "),i("a",{class:"header-anchor",href:"#architecture-overview","aria-label":'Permalink to "Architecture Overview"'},"​")],-1)),e[4]||(e[4]=i("p",null,"GameFilter XDP is two programs and a shared-types crate, all Rust:",-1)),(t(),o(d,null,{default:a(()=>[r(n,{id:"mermaid-6",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20subgraph%20Kernel%0A%20%20%20%20%20%20%20%20XDP%5Bgamefilter-ebpf%3Cbr%2F%3EXDP%20program%3Cbr%2F%3Eaya-ebpf%2C%20no_std%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Userspace%0A%20%20%20%20%20%20%20%20CLI%5Bgamefilter%20CLI%20%2F%20loader%3Cbr%2F%3Eaya%5D%0A%20%20%20%20%20%20%20%20D%5Bgamefilter%20daemon%3Cbr%2F%3Eaxum%20HTTP%20API%5D%0A%20%20%20%20%20%20%20%20S%5BOpenShield%20sync%20task%3Cbr%2F%3Ereqwest%5D%0A%20%20%20%20end%0A%20%20%20%20OS%5BOpenShield-XDP%3Cbr%2F%3Eapi%20%2F%20file%20%2F%20pinned%20maps%5D%0A%20%20%20%20MAPS%5B(Pinned%20maps%3Cbr%2F%3E%2Fsys%2Ffs%2Fbpf%2Fgamefilter)%5D%0A%0A%20%20%20%20XDP%20%3C--%3E%20MAPS%0A%20%20%20%20CLI%20%3C--%3E%20MAPS%0A%20%20%20%20D%20%3C--%3E%20MAPS%0A%20%20%20%20S%20--%3E%20MAPS%0A%20%20%20%20OS%20--%3E%20S%0A%20%20%20%20D%20---%20S%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=l('<ul><li><strong>eBPF kernel program</strong> (<code>gamefilter-ebpf/</code>) — a single <code>#[xdp]</code> entry point written with aya-ebpf (<code>no_std</code>, <code>no_main</code>). Parses IPv4/IPv6 + TCP/UDP, runs the whitelist/blacklist/port/admission/validator pipeline, and returns <code>XDP_PASS</code> or <code>XDP_DROP</code>. Non-IP or unparseable traffic is passed — fail-open by design.</li><li><strong>Userspace loader + CLI</strong> (<code>gamefilter/</code>, aya) — loads the object, populates the maps, attaches native-first with generic fallback, pins the link and every map, and exits. All CLI commands (<code>status</code>, <code>whitelist</code>, …) reopen the pinned maps, so they work without any resident process.</li><li><strong>API daemon</strong> (<code>gamefilter daemon</code>, axum) — the management plane: token-authenticated, per-IP rate-limited REST API, plus the OpenShield sync task when enabled.</li><li><strong>OpenShield sync</strong> (<code>sync.rs</code>) — polls OpenShield&#39;s lists (API, JSON file, or direct pinned-map read) and diffs them into the kernel maps; local CLI/API entries are marker-tagged and never touched.</li><li><strong>Shared types</strong> (<code>gamefilter-common/</code>) — <code>repr(C)</code> structs that are the kernel ABI (<code>FilterRule</code>, <code>AdmitKey</code>, <code>RuleStats</code>, …), compiled into both sides.</li></ul><nav class="table-of-contents"><ul><li><a href="#map-layout">Map layout</a></li><li><a href="#packet-pipeline">Packet pipeline</a></li><li><a href="#admission-ban-state-machine">Admission / ban state machine</a></li><li><a href="#hot-reload">Hot reload</a></li><li><a href="#file-layout">File layout</a></li></ul></nav><hr><h2 id="map-layout" tabindex="-1">Map layout <a class="header-anchor" href="#map-layout" aria-label="Permalink to &quot;Map layout&quot;">​</a></h2><p>All maps are pinned under <code>/sys/fs/bpf/gamefilter/maps/</code> at load; the attach itself is pinned as <code>/sys/fs/bpf/gamefilter/link</code> (an fd link — removing the pin detaches the program).</p><table tabindex="0"><thead><tr><th>Map</th><th>Type</th><th>Key → Value</th><th>Notes</th></tr></thead><tbody><tr><td><code>FILTER_MAP</code></td><td>ARRAY (64)</td><td>slot → <code>FilterRule</code></td><td>The rule table; position = slot used in stats</td></tr><tr><td><code>PORT_MAP</code></td><td>ARRAY (131072)</td><td><code>proto_idx &lt;&lt; 16 | port</code> → <code>u16</code></td><td><code>proto_idx</code> 0 = TCP, 1 = UDP. Stores <strong>rule_idx + 1</strong> — 0 (zero-init) means &quot;port not owned&quot;</td></tr><tr><td><code>ADMIT_MAP</code></td><td>LRU_HASH (65536)</td><td><code>AdmitKey{addr[16], rule}</code> → <code>{admit_until_ns}</code></td><td>Sliding admission deadline (monotonic ns). Also written with <code>rule = 0xFFFF</code> as an any-rule marker for fragments</td></tr><tr><td><code>FAIL_MAP</code></td><td>LRU_HASH (65536)</td><td><code>AdmitKey</code> → <code>{window_start_ns, count}</code></td><td>Validation failures inside a 60-second window</td></tr><tr><td><code>WHITELIST</code></td><td>HASH (65536)</td><td><code>addr[16]</code> → <code>u64</code></td><td>Checked first — full bypass. Value 1 = local, 2 = synced</td></tr><tr><td><code>BLACKLIST</code></td><td>HASH (65536)</td><td><code>addr[16]</code> → <code>u64</code></td><td>Value 0 = permanent; otherwise monotonic-ns expiry (temp-bans)</td></tr><tr><td><code>STATS</code></td><td>PERCPU_ARRAY (65)</td><td>slot → <code>RuleStats</code></td><td>One slot per rule; slot 64 is the global entry. Userspace sums across CPUs</td></tr><tr><td><code>CONFIG</code></td><td>ARRAY (1)</td><td>0 → <code>{default_drop, enabled}</code></td><td>Global switches, rewritten on every reload</td></tr></tbody></table><p>Key conventions:</p><ul><li><strong>IP keys are <code>[u8; 16]</code></strong> — IPv4 in the first 4 bytes (rest zero), full IPv6 otherwise. One map family serves both families.</li><li><strong>Admission is per (source, rule)</strong> — being admitted for Minecraft does not admit you to the SSH filter.</li><li>LRU for <code>ADMIT_MAP</code>/<code>FAIL_MAP</code> means flood churn evicts entries instead of failing inserts; the whitelist/blacklist are plain HASH so synced and manual entries are never evicted.</li><li>The validator reads payload at fixed offsets with direct packet access; the one dynamic-offset read (MC Java next-state byte) goes through <code>bpf_xdp_load_bytes</code>, which validates at runtime — available since kernel 5.9, comfortably above the 5.15 floor.</li></ul><h2 id="packet-pipeline" tabindex="-1">Packet pipeline <a class="header-anchor" href="#packet-pipeline" aria-label="Permalink to &quot;Packet pipeline&quot;">​</a></h2>',9)),(t(),o(d,null,{default:a(()=>[r(n,{id:"mermaid-204",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5BPacket%20arrives%5D%20--%3E%20EN%7Benabled%3F%7D%0A%20%20%20%20EN%20--%20no%20--%3E%20PASS%5BXDP_PASS%5D%0A%20%20%20%20EN%20--%20yes%20--%3E%20PARSE%7BParse%20IPv4%2FIPv6%3Cbr%2F%3E%2B%20TCP%2FUDP%7D%0A%20%20%20%20PARSE%20--%20non-IP%20%2F%20unparseable%20--%3E%20PASS%0A%20%20%20%20PARSE%20--%20ok%20--%3E%20WL%7BWHITELIST%3F%7D%0A%20%20%20%20WL%20--%20yes%20--%3E%20PASS%0A%20%20%20%20WL%20--%20no%20--%3E%20BL%7BBLACKLIST%3F%3Cbr%2F%3E0%20%3D%20permanent%2C%3Cbr%2F%3Eelse%20expiry%20%3E%20now%7D%0A%20%20%20%20BL%20--%20yes%20--%3E%20DROP%5BXDP_DROP%5D%0A%20%20%20%20BL%20--%20no%20--%3E%20FRAG%7BNon-first%3Cbr%2F%3Efragment%3F%7D%0A%20%20%20%20FRAG%20--%20yes%20--%3E%20FA%7BAny-rule%20admission%3Cbr%2F%3Emarker%20live%3F%7D%0A%20%20%20%20FA%20--%20yes%20--%3E%20PASS%0A%20%20%20%20FA%20--%20no%20--%3E%20DROP%0A%20%20%20%20FRAG%20--%20no%20--%3E%20OWN%7BPORT_MAP%3Cbr%2F%3Eowned%3F%7D%0A%20%20%20%20OWN%20--%20no%20--%3E%20DEF%7Bdefault_drop%3F%7D%0A%20%20%20%20DEF%20--%20yes%20--%3E%20DROP%0A%20%20%20%20DEF%20--%20no%20--%3E%20PASS%0A%20%20%20%20OWN%20--%20yes%20--%3E%20RD%7BRule%20enabled%3F%7D%0A%20%20%20%20RD%20--%20no%20--%3E%20PASS%0A%20%20%20%20RD%20--%20yes%20--%3E%20ADM%7BAdmitted%20for%3Cbr%2F%3Ethis%20rule%3F%7D%0A%20%20%20%20ADM%20--%20yes%20--%3E%20REF%5BRefresh%20sliding%20TTL%5D%20--%3E%20PASS%0A%20%20%20%20ADM%20--%20no%20--%3E%20NOP%7BTCP%20with%3Cbr%2F%3Eno%20payload%3F%7D%0A%20%20%20%20NOP%20--%20yes%20--%3E%20PASS2%5BXDP_PASS%3Cbr%2F%3Eno%20admission%5D%0A%20%20%20%20NOP%20--%20no%20--%3E%20SZ%7Bmin_size%20%E2%89%A4%20len%3Cbr%2F%3E%E2%89%A4%20max_size%3F%7D%0A%20%20%20%20SZ%20--%20no%20--%3E%20FAIL%0A%20%20%20%20SZ%20--%20yes%20--%3E%20VAL%7BValidator%3A%3Cbr%2F%3Emc_java%20%2F%20raknet%20%2F%3Cbr%2F%3Efivem%20%2F%20source_engine%20%2F%3Cbr%2F%3Essh_banner%20%2F%20generics%7D%0A%20%20%20%20VAL%20--%20valid%20--%3E%20ADMIT%5BAdmit%20source%20for%3Cbr%2F%3Eadmission_ttl_sec%3Cbr%2F%3E%2B%20any-rule%20marker%5D%20--%3E%20PASS%0A%20%20%20%20VAL%20--%20invalid%20--%3E%20FAIL%5BDROP%20%2B%20count%20failure%3Cbr%2F%3Ein%2060s%20window%5D%0A%20%20%20%20FAIL%20--%3E%20BAN%7Bcount%20%E2%89%A5%20max_failures%3Cbr%2F%3Eand%20ban_sec%20%3E%200%3F%7D%0A%20%20%20%20BAN%20--%20yes%20--%3E%20TB%5BBLACKLIST%20%E2%86%90%20now%20%2B%20ban_sec%5D%0A%20%20%20%20BAN%20--%20no%20--%3E%20DROP%0A%20%20%20%20TB%20--%3E%20DROP%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=l('<p>Pipeline properties worth knowing:</p><ul><li><strong>Whitelist outranks everything; blacklist outranks all validation.</strong></li><li><strong>TCP handshake packets pass but never admit</strong> — SYN/ACK with no payload gets <code>XDP_PASS</code> without touching <code>ADMIT_MAP</code>. Only a data packet that passes the validator admits a source.</li><li><strong>Fragments are fail-closed for strangers</strong> — a non-first fragment has no visible L4 header, so it only passes if the source holds a live admission (the <code>0xFFFF</code> any-rule marker written alongside every admission).</li><li><strong>IPv6 extension headers are not walked</strong> — such packets are treated as unparseable and passed, same as non-IP traffic.</li><li>Every counter bump hits both the rule&#39;s <code>STATS</code> slot and the global slot 64, per-CPU (no atomic contention at line rate).</li></ul><h2 id="admission-ban-state-machine" tabindex="-1">Admission / ban state machine <a class="header-anchor" href="#admission-ban-state-machine" aria-label="Permalink to &quot;Admission / ban state machine&quot;">​</a></h2>',3)),(t(),o(d,null,{default:a(()=>[r(n,{id:"mermaid-238",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20Unknown%0A%20%20%20%20Unknown%20--%3E%20Admitted%3A%20packet%20passes%20validator%3Cbr%2F%3E(admit%20for%20admission_ttl_sec)%0A%20%20%20%20Admitted%20--%3E%20Admitted%3A%20any%20further%20packet%3Cbr%2F%3E(sliding%20TTL%20refresh)%0A%20%20%20%20Admitted%20--%3E%20Unknown%3A%20TTL%20expires%20(idle)%0A%20%20%20%20Unknown%20--%3E%20Failed%3A%20validation%20fails%3Cbr%2F%3E(drop%20%2B%20count%20in%2060s%20window)%0A%20%20%20%20Failed%20--%3E%20Unknown%3A%20window%20rolls%20over%3Cbr%2F%3Ewithout%20reaching%20max_failures%0A%20%20%20%20Failed%20--%3E%20Banned%3A%20failures%20%E2%89%A5%20max_failures%3Cbr%2F%3Ein%2060s%20(ban_sec%20%3E%200)%0A%20%20%20%20Banned%20--%3E%20Unknown%3A%20ban_sec%20expires%0A%20%20%20%20Unknown%20--%3E%20Whitelisted%3A%20CLI%20%2F%20API%20%2F%20config%20%2F%20sync%0A%20%20%20%20Banned%20--%3E%20Whitelisted%3A%20whitelist%20add%3Cbr%2F%3E(checked%20first%2C%20outranks%20ban)%0A"})]),fallback:a(()=>[...e[2]||(e[2]=[s(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=l(`<p>State is entirely in the LRU maps — there is no userspace bookkeeping, so the kernel decision path never waits on the daemon.</p><h2 id="hot-reload" tabindex="-1">Hot reload <a class="header-anchor" href="#hot-reload" aria-label="Permalink to &quot;Hot reload&quot;">​</a></h2><p><code>gamefilter reload</code> (and <code>POST /api/v1/reload</code>) re-push state through the <strong>pinned maps</strong> without reloading the object or detaching:</p><ol><li>Rewrite the <code>CONFIG</code> slot (<code>enabled</code>, <code>default_drop</code>).</li><li>Zero all 64 <code>FILTER_MAP</code> slots, then write the new rules.</li><li>Sweep all 131072 <code>PORT_MAP</code> entries to 0, then re-stamp ownership (<code>rule_idx + 1</code>).</li></ol><p>Admissions, lists, and failure windows survive a reload untouched. Static <code>whitelist:</code>/<code>blacklist:</code> from the YAML are only seeded at <code>load</code>.</p><h2 id="file-layout" tabindex="-1">File layout <a class="header-anchor" href="#file-layout" aria-label="Permalink to &quot;File layout&quot;">​</a></h2><p>Installed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/opt/gamefilter/gamefilter            # userspace binary</span></span>
<span class="line"><span>/opt/gamefilter/gamefilter-ebpf.o     # XDP object</span></span>
<span class="line"><span>/usr/local/bin/gamefilter             # symlink → /opt/gamefilter/gamefilter</span></span>
<span class="line"><span>/etc/gamefilter/gamefilter.yaml       # config (chmod 600)</span></span>
<span class="line"><span>/var/lib/gamefilter/state.json        # load-time snapshot (interface, mode, filter table)</span></span>
<span class="line"><span>/sys/fs/bpf/gamefilter/link           # pinned XDP link (the attachment)</span></span>
<span class="line"><span>/sys/fs/bpf/gamefilter/maps/*         # pinned maps</span></span>
<span class="line"><span>/etc/systemd/system/gamefilter-loader.service   # oneshot: load / unload</span></span>
<span class="line"><span>/etc/systemd/system/gamefilter-api.service      # daemon: API + sync</span></span></code></pre></div><p>Source tree:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gamefilter/            # userspace (aya, axum, clap)</span></span>
<span class="line"><span>  src/main.rs          # CLI definition</span></span>
<span class="line"><span>  src/bpf_loader.rs    # object load, rule push, attach, pin</span></span>
<span class="line"><span>  src/cli.rs           # status JSON, lists, reload-via-pins, key mgmt</span></span>
<span class="line"><span>  src/api.rs           # axum router, auth, rate limiting</span></span>
<span class="line"><span>  src/daemon.rs        # load / daemon entry points</span></span>
<span class="line"><span>  src/sync.rs          # OpenShield list sync (api | file | maps)</span></span>
<span class="line"><span>  src/maps.rs          # pinned-map access helpers</span></span>
<span class="line"><span>  src/config.rs        # YAML schema</span></span>
<span class="line"><span>gamefilter-ebpf/       # XDP program (aya-ebpf, no_std)</span></span>
<span class="line"><span>gamefilter-common/     # shared repr(C) kernel ABI types</span></span>
<span class="line"><span>configs/               # example config</span></span>
<span class="line"><span>systemd/               # unit files</span></span>
<span class="line"><span>scripts/test-rig.sh    # veth integration test with crafted game packets</span></span></code></pre></div>`,10))])}const F=c(A,[["render",h]]);export{y as __pageData,F as default};
